const { existsSync, readFileSync } = await import('node:fs');
const inputPath = process.env['FILE_PATH'];
if (!inputPath || !existsSync(inputPath)) {
  throw new Error('Input file missing or unreadable');
}
globalThis.fileBuffer = readFileSync(inputPath);

const { chromium } = await import('playwright');
const browser = await chromium.launch();
const context = await browser.newContext();
const page = await context.newPage();
const path = await import('node:path');
const scriptPath = path.join(process.cwd(), 'node_modules', 'qr-scanner', 'qr-scanner.min.js');
await page.addScriptTag({ path: scriptPath });
const base64 = globalThis.fileBuffer.toString('base64');
await page.exposeFunction('getImageBase64', () => base64);
const result = await page.evaluate(async () => {
  const b64 = await window.getImageBase64();
  const binary = Uint8Array.from(atob(b64), c => c.charCodeAt(0));
  const blob = new Blob([binary.buffer], { type: 'image/png' });
  // QrScanner is available as a global after the script tag
  const decoded = await QrScanner.scanImage(blob);
  return decoded;
});
globalThis.scanResult = result;
await browser.close();

if (globalThis.scanResult == null) {
  throw new Error('QR code could not be decoded from the provided image');
}
